<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {P1Config,P1SkillId} from '@/views/AgentWork/interface';
import {parseRuleRequest,taskParameters,taskRule,type RuleProposal} from './ruleLanguage';
const props=defineProps<{config:P1Config;scope?:P1SkillId}>();
const emit=defineEmits<{confirm:[proposal:RuleProposal]}>();
const completeRules=computed(()=>{if(!proposal.value)return [];const ids=props.scope?[props.scope]:proposal.value.config.selectedSkills.filter(id=>taskRule(props.config,id)!==taskRule(proposal.value!.config,id));return ids.map(id=>({id,rows:taskParameters(proposal.value!.config,id).filter(row=>!props.scope||!row.key.endsWith('enabled')).map(row=>({...row,before:taskParameters(props.config,id).find(old=>old.key===row.key)?.value}))}));});
const text=ref('');const proposal=ref<RuleProposal>();const message=ref('');
watch(text,()=>{proposal.value=undefined;message.value='';});
watch(()=>JSON.stringify(props.config),()=>{proposal.value=undefined;},{deep:true});
function parse(){proposal.value=parseRuleRequest(text.value,props.config,props.scope);message.value=proposal.value.changes.length?'只调整您提到的内容，其他参数沿用当前规则。请核对完整规则后确认。':'没有识别到配置调整，请补充任务、数值和单位。';}
function confirm(){if(!proposal.value||proposal.value.unresolved.length)return;emit('confirm',proposal.value);proposal.value=undefined;text.value='';message.value='已确认调整，请查看当前规则及保存结果。';}
</script>
<template><section class="p1-language"><label>规则调整<textarea v-model="text" :rows="scope?2:3" aria-label="自然语言规则调整" :placeholder="scope?'只填写要改的内容，例如：重复提醒间隔改为20分钟。其他参数保留原值。':'例如：停车时长改为45分钟；开启天气监听。其他参数保留原值。'"/></label><small>本地解析演示，尚未接入LLM。无法识别的内容会列出，不会自动保存。</small><button type="button" :disabled="!text.trim()" @click="parse">解析调整内容</button><p role="status">{{message}}</p><template v-if="proposal"><ul v-if="!scope"><li v-for="change in proposal.changes" :key="change">{{change}}</li></ul><section v-for="rule in completeRules" :key="rule.id" class="complete-rule"><h4>调整后的完整规则</h4><div v-for="row in rule.rows" :key="row.key" class="parameter-preview"><span>{{row.label}}</span><strong>{{row.value}}</strong><small :class="{changed:row.before!==row.value}">{{row.before===row.value?'保持原值':`由${row.before}调整`}}</small></div></section><p v-for="item in proposal.unresolved" :key="item" class="p1-error">{{item}}</p><button type="button" :disabled="!proposal.changes.length||!!proposal.unresolved.length" @click="confirm">确认调整</button><button type="button" @click="proposal=undefined">取消调整</button></template></section></template>
<style scoped>.p1-language{padding:14px 0;border-top:1px solid #ddd;margin-top:16px;font-size:13px}.p1-language textarea{display:block;width:100%;padding:10px;border:1px solid #ccc;border-radius:6px;margin:8px 0}.p1-language button{border:1px solid #ccc;background:white;border-radius:5px;padding:7px 12px;margin:8px 8px 0 0}.p1-language button:disabled{opacity:.45}.p1-language small{color:#667487}.p1-language li{margin:8px 0}.complete-rule{margin:14px 0;border:1px solid #dfe4e9;border-radius:5px;padding:10px 12px}.complete-rule h4{font-size:13px;margin:0 0 8px}.parameter-preview{display:grid;grid-template-columns:130px 1fr auto;gap:8px;padding:7px 0;border-top:1px solid #eee}.parameter-preview strong{font-weight:500}.parameter-preview .changed{color:#315a80}@media(max-width:600px){.parameter-preview{grid-template-columns:1fr}.parameter-preview small{justify-self:start}}</style>
